# ============================================================
#  YKAY EDUPORTAL - PHASE 5B INGESTION SCRIPT (Base64 edition)
#  Target: C:\Users\USER\Desktop\PROJECTS\ykay_edu\envoys-site
#  Compatible with Windows PowerShell 5.1 and PowerShell 7+
#  NOTE: uses -LiteralPath so [slug]/[token] dynamic folders write correctly
# ============================================================

$ProjectRoot = "C:\Users\USER\Desktop\PROJECTS\ykay_edu\envoys-site"

if (-not (Test-Path -LiteralPath $ProjectRoot)) {
    Write-Host "ERROR: Project root not found at $ProjectRoot" -ForegroundColor Red
    exit 1
}

function Write-ProjectFileB64 {
    param(
        [string]$RelativePath,
        [string[]]$Chunks
    )
    $FullPath = Join-Path $ProjectRoot $RelativePath
    $Dir = Split-Path $FullPath -Parent
    if ($Dir -and -not (Test-Path -LiteralPath $Dir)) { New-Item -ItemType Directory -Force -LiteralPath $Dir | Out-Null }
    $Base64 = [string]::Join("", $Chunks)
    $Bytes = [System.Convert]::FromBase64String($Base64)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    Write-Host ("Updated " + $RelativePath + " (" + $Bytes.Length + " bytes)") -ForegroundColor Green
}

Write-Host ""
Write-Host "Applying Phase 5B..." -ForegroundColor Cyan
Write-Host ""
# --- app/api/admin/id-cards/route.ts ---
$chunks = @(
""
)
Write-ProjectFileB64 -RelativePath "app/api/admin/id-cards/route.ts" -Chunks $chunks

# --- app/admin/id-cards/page.tsx ---
$chunks = @(
""
,""
,""
,""
)
Write-ProjectFileB64 -RelativePath "app/admin/id-cards/page.tsx" -Chunks $chunks

# --- app/verify/id/[token]/page.tsx ---
